{"command": "cd /tmp && cat > bt.py <<'EOF'
import subprocess,time,os,select,fcntl,sys,re,collections
env=dict(os.environ,TERM='xterm-256color')
dur=float(sys.argv[1]); extra=sys.argv[2:]
p=subprocess.Popen(['/workspace/executable','-m','bruteforce']+extra,stdout=subprocess.PIPE,env=env)
fd=p.stdout.fileno(); fcntl.fcntl(fd,fcntl.F_SETFL,fcntl.fcntl(fd,fcntl.F_GETFL)|os.O_NONBLOCK)
t0=time.time(); buf=b''; frames=[]  # (time, content)
while time.time()-t0<dur:
    r,_,_=select.select([fd],[],[],0.002)
    if r:
        b=os.read(fd,65536)
        if not b: break
        buf+=b
        while b'\r' in buf:
            i=buf.index(b'\r'); frames.append((time.time()-t0, buf[:i])); buf=buf[i+1:]
p.terminate(); p.wait()
# classify
seq=[]
for t,f in frames:
    if f.startswith(b'=> Hashes to decrypt'): seq.append((t,'HDR',None))
    elif re.fullmatch(rb'  [0-9a-f]{64}',f): seq.append((t,'HASH',len(f)-2))
    elif f.startswith(b'=> Extracting Rainbow Table ['): seq.append((t,'RB',None))
    elif f==b'=> Begin matching': seq.append((t,'BEGIN',None))
    else:
        m=re.match(rb'^(?:\x1b\[(\d+)A)? :: \x1b\[32m([0-9a-f]*)\x1b\[0m\x1b\[31m([0-9a-f]*)\x1b\[0m ::$',f)
        if m: seq.append((t,'MATCH',(int(m.group(1) or 0), len(m.group(2)), len(m.group(2))+len(m.group(3)))))
        else: seq.append((t,'OTH',f[:30]))
# phases
prev=None
groups=[]
for t,k,v in seq:
    if k in ('HDR','BEGIN','RB','HASH','OTH'):
        print(f"{t:7.3f} {k} {v}")
    else:
        groups.append((t,v))
