mod data;
mod io;
mod modules;

use clap::{CommandFactory, Parser};
use clap_complete::{generate, Shell};
use rand::seq::SliceRandom;
use std::sync::atomic::{AtomicBool, Ordering};

#[derive(Parser, Debug)]
#[command(name = "genact", version, about = "A nonsense activity generator")]
struct Args {
    /// List available modules
    #[arg(short, long)]
    list_modules: bool,

    /// Run only these modules
    #[arg(short, long, value_enum)]
    modules: Vec<modules::Modules>,

    /// Global speed factor
    #[arg(short, long, default_value_t = 1.0, value_parser = clap::value_parser!(f64))]
    speed_factor: f64,

    /// Instantly print this many lines
    #[arg(short, long, default_value_t = 0)]
    instant_print_lines: u32,

    /// Keep the computer awake and the display on while genact is running
    #[arg(long)]
    inhibit: bool,

    /// Exit after running for this long (format example: 2h10min)
    #[arg(long, value_name = "EXIT_AFTER_TIME")]
    exit_after_time: Option<String>,

    /// Exit after running this many modules
    #[arg(long, value_name = "EXIT_AFTER_MODULES")]
    exit_after_modules: Option<usize>,

    /// Generate completion file for a shell
    #[arg(long, value_enum)]
    print_completions: Option<Shell>,

    /// Generate man page
    #[arg(long)]
    print_manpage: bool,
}

static EXITED: AtomicBool = AtomicBool::new(false);

extern "C" fn signal_handler(_signal: libc::c_int) {
    io::print_exit_message();
    unsafe { libc::_exit(0) };
}

fn main() {
    let args = Args::parse();

    if let Some(shell) = args.print_completions {
        let mut cmd = Args::command();
        generate(shell, &mut cmd, "genact", &mut std::io::stdout());
        return;
    }
    if args.print_manpage {
        let man = clap_mangen::Man::new(Args::command());
        man.render(&mut std::io::stdout()).unwrap();
        return;
    }

    if args.list_modules {
        println!("Available modules:");
        for module in modules::MODULES {
            println!("  {}", module.name);
        }
        return;
    }

    if args.speed_factor < 0.01 {
        // validated by clap
    }

    io::init(args.speed_factor, args.instant_print_lines);

    if let Some(spec) = &args.exit_after_time {
        match data::parse_duration(spec) {
            Ok(d) => io::set_exit_deadline(d),
            Err(e) => {
                // clap value parser handles this; unreachable
                let _ = e;
            }
        }
    }

    unsafe {
        libc::signal(libc::SIGINT, signal_handler as usize);
        libc::signal(libc::SIGTERM, signal_handler as usize);
        libc::signal(libc::SIGHUP, signal_handler as usize);
    }

    if args.inhibit {
        io::setup_inhibit();
    }

    let mut selected: Vec<&modules::Module> = if args.modules.is_empty() {
        modules::MODULES.iter().collect()
    } else {
        args.modules
            .iter()
            .map(|m| modules::by_name(m.as_str()))
            .collect()
    };

    let mut rng = rand::thread_rng();
    selected.shuffle(&mut rng);

    let mut modules_run = 0;
    for module in selected {
        if let Some(max) = args.exit_after_modules {
            if modules_run >= max {
                break;
            }
        }
        modules_run += 1;
        (module.run)();
    }
}
