use std::io::{self, Write};
use std::os::unix::net::UnixStream;
use std::sync::atomic::{AtomicI64, AtomicU32, AtomicU64, AtomicUsize, Ordering};
use std::thread;
use std::time::{Duration, Instant};

static SPEED_FACTOR: AtomicU64 = AtomicU64::new(0);
static INSTANT_PRINT_LINES: AtomicU32 = AtomicU32::new(0);
static LINES_PRINTED: AtomicUsize = AtomicUsize::new(0);
static EXIT_DEADLINE: AtomicI64 = AtomicI64::new(-1);
static EXIT_MESSAGE: &[u8] = b"Saving work to disk...\n";

pub fn init(speed_factor: f64, instant_print_lines: u32) {
    SPEED_FACTOR.store(speed_factor.to_bits(), Ordering::Relaxed);
    INSTANT_PRINT_LINES.store(instant_print_lines, Ordering::Relaxed);
}

pub fn speed_factor() -> f64 {
    f64::from_bits(SPEED_FACTOR.load(Ordering::Relaxed))
}

pub fn set_exit_deadline(duration: Duration) {
    let deadline = Instant::now() + duration;
    let millis = deadline
        .saturating_duration_since(Instant::now())
        .as_millis() as i64;
    EXIT_DEADLINE.store(millis, Ordering::Relaxed);
}

/// Sleep for the given amount of time, scaled by the global speed factor.
pub fn sleep(duration: Duration) {
    let lines = LINES_PRINTED.fetch_add(1, Ordering::Relaxed);
    if (lines as u32) <= INSTANT_PRINT_LINES.load(Ordering::Relaxed) {
        return;
    }
    let speed = speed_factor();
    let scaled = duration.as_secs_f64() * 1000.0 / speed;
    let mut millis = scaled.floor() as u64;
    if scaled.is_nan() || millis == 0 {
        millis = 0;
    }
    millis += 1;
    thread::sleep(Duration::from_millis(millis));
    check_exit_deadline();
}

fn check_exit_deadline() {
    let deadline = EXIT_DEADLINE.load(Ordering::Relaxed);
    if deadline < 0 {
        return;
    }
    if Instant::now()
        .duration_since(Instant::now() - Duration::from_millis(deadline as u64))
        .as_millis()
        >= deadline as u128
    {
        print_exit_message();
        std::process::exit(0);
    }
}

fn write_out(b: &[u8]) {
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    stdout.write_all(&b).unwrap();
    lock.flush().unwrap();
}

pub fn print_raw(s: &str) {
    write_out(s.as_bytes());
}

pub fn print_line(line: &str) {
    write_out(line.as_bytes());
    write_out(b"\r\n");
}

/// Print a message and exit; used by the signal handling thread.
pub fn print_exit_message() {
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(EXIT_MESSAGE);
    let _ = lock.flush();
}

/// Get the width of the terminal attached to stdin.
pub fn terminal_width() -> u16 {
    let mut winsize = libc::winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let result = unsafe { libc::ioctl(libc::STDIN_FILENO, libc::TIOCGWINSZ, &mut winsize) };
    if result == 0 {
        return winsize.ws_col;
    }
    panic!("Couldn't get terminal width. Is an interactive terminal attached?");
}

/// Try to keep the computer awake while genact runs.
pub fn setup_inhibit() {
    let path = inhibit_bus_path();
    match UnixStream::connect(&path) {
        Ok(_stream) => {
            std::mem::forget(_stream);
        }
        Err(e) => {
            println!("WARN: failed to set up idle inhibition: system: I/O error: {}", e);
        }
    }
}

fn inhibit_bus_path() -> String {
    if let Ok(dir) = std::env::var("XDG_RUNTIME_DIR") {
        return format!("{}/bus", dir);
    }
    let uid = unsafe { libc::getuid() };
    format!("/run/user/{}/bus", uid)
}
