use std::io::{self, Write};
use std::os::unix::net::UnixStream;
use std::sync::atomic::{AtomicI64, AtomicU32, AtomicU64, AtomicUsize, Ordering};
use std::thread;
use std::time::{Duration, Instant};

/// Global speed factor, stored as the raw bits of an `f64` so it can live in a static.
static SPEED_FACTOR: AtomicU64 = AtomicU64::new(0);
/// Number of lines that should be printed instantly, without sleeping in between.
static INSTANT_PRINT_LINES: AtomicU32 = AtomicU32::new(0);
/// Total number of sleep points reached so far.
static LINES_PRINTED: AtomicUsize = AtomicUsize::new(0);
/// Exit deadline, in milliseconds since the program started. `-1` when not requested.
static EXIT_DEADLINE: AtomicI64 = AtomicI64::new(-1);
/// Message that is printed whenever the program gets interrupted.
static EXIT_MESSAGE: &[u8] = b"Saving work to disk...\n";

/// Set up the global io configuration.
pub fn init(speed_factor: f64, instant_print_lines: u32) {
    SPEED_FACTOR.store(speed_factor.to_bits(), Ordering::Relaxed);
    INSTANT_PRINT_LINES.store(instant_print_lines, Ordering::Relaxed);
}

/// The global speed factor.
pub fn speed_factor() -> f64 {
    f64::from_bits(SPEED_FACTOR.load(Ordering::Relaxed))
}

/// Remember that genact should exit after `duration` has elapsed.
pub fn set_exit_deadline(duration: Duration) {
    let deadline = Instant::now() + duration;
    EXIT_DEADLINE.store(elapsed_millis_of(deadline) as i64, Ordering::Relaxed);
}

fn elapsed_millis_of(deadline: Instant) -> u128 {
    let start = program_start();
    deadline.saturating_duration_since(start).as_millis()
}

fn program_start() -> Instant {
    PROGRAM_START.get()
}

struct ProgramStart(Option<Instant>);
impl ProgramStart {
    const fn new() -> Self {
        ProgramStart(None)
    }
    fn get(&self) -> Instant {
        match self.0 {
            Some(v) => v,
            None => Instant::now(),
        }
    }
}

static PROGRAM_START: ProgramStart = ProgramStart::new();

/// Sleep for the given duration, scaled by the global speed factor.
///
/// Sleeps are skipped entirely for the first `--instant-print-lines` lines.
pub fn sleep(duration: Duration) {
    let lines = LINES_PRINTED.fetch_add(1, Ordering::Relaxed);
    if (lines as u32) <= INSTANT_PRINT_LINES.load(Ordering::Relaxed) {
        return;
    }
    let scaled = duration.as_secs_f64() * 1000.0 / speed_factor();
    let mut millis = if scaled.is_nan() { 0.0 } else { scaled.floor() };
    if millis < 0.0 {
        millis = 0.0;
    }
    thread::sleep(Duration::from_millis(millis as u64 + 1));
    check_exit_deadline();
}

fn check_exit_deadline() {
    let deadline = EXIT_DEADLINE.load(Ordering::Relaxed);
    if deadline < 0 {
        return;
    }
    if elapsed_millis() as i64 >= deadline {
        print_exit_message();
        std::process::exit(0);
    }
}

fn elapsed_millis() -> u128 {
    program_start().elapsed().as_millis()
}

fn write_out(b: &[u8]) {
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    stdout.write_all(&b).unwrap();
    lock.flush().unwrap();
}
