            Modules::Mkinitcpio => "mkinitcpio",
            Modules::Rkhunter => "rkhunter",
            Modules::Simcity => "simcity",
            Modules::Terraform => "terraform",
            Modules::Uv => "uv",
            Modules::Weblog => "weblog",
            Modules::Wpt => "wpt",
        }
    }
