}

fn parse_module_count(s: &str) -> Result<u32, String> {
    let value: u32 = s.parse()?;
    if value == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(value)
}

extern "C" fn signal_handler(_signal: libc::c_int) {
    let _ = _signal;
}

fn main() {
    let args = Args::parse();

    if let Some(shell) = args.print_completions {
        let mut cmd = Args::command();
        generate(shell, &mut cmd, "genact", &mut std::io::stdout());
        return;
    }
    if args.print_manpage {
        let man = clap_mangen::Man::new(Args::command());
        let mut out = std::io::stdout();
        man.render(&mut out).unwrap();
        return;
    }

    if args.list_modules {
        println!("Available modules:");
        for module in modules::MODULES {
            println!("  {}", module.name);
        }
        return;
    }

    io::init(args.speed_factor, args.instant_print_lines);
    if let Some(duration) = args.exit_after_time {
        io::set_exit_deadline(duration);
    }
    let exit_after_modules = args.exit_after_modules;

    modules::start_signal_thread();

    if args.inhibit {
        io::setup_inhibit();
    }

    let mut selected: Vec<&modules::Module> = if args.modules.is_empty() {
        modules::MODULES.iter().collect()
    } else {
        args.modules
            .iter()
            .map(|m| modules::by_name(m.as_str()))
            .collect()
    };

    let mut rng = rand::thread_rng();
    selected.shuffle(&mut rng);

    let mut modules_run: u32 = 0;
    for module in selected {
        if let Some(max) = exit_after_modules {
            if modules_run >= max {
                break;
            }
        }
        modules_run += 1;
        (module.run)();
    }
}
