/// Spawn the thread that reacts to ctrl-c / termination signals.
pub fn start_signal_thread() {
    let builder = std::thread::Builder::new().name("ctrl-c".to_string());
    let handle = builder
        .spawn(|| {
            let signals = signal_hook::iterator::Signals::new(&[
                signal_hook::consts::SIGINT,
                signal_hook::consts::SIGTERM,
                signal_hook::consts::SIGHUP,
            ])
            .unwrap_or_else(|_| std::process::exit(1));
            for signal in signals.forever() {
                let _ = signal;
                crate::io::print_exit_message();
                std::process::exit(0);
            }
        })
        .unwrap();
    let _ = handle;
}
