                .value_name("EXIT_AFTER_MODULES")
                .value_parser(parse_module_count)
                .help("Exit after running this many modules"),
        )
        .arg(
            Arg::new("print-completions")
                .long("print-completions")
                .value_name("shell")
                .value_parser(clap::builder::PossibleValuesParser::new(
                    SHELLS.map(|s| s.to_string()),
