    if value == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(value)
}

fn main() {
    let matches = cli().get_matches();

    if let Some(shell) = matches.get_one::<String>("print-completions") {
        let shell = Shell::from_str(shell).unwrap();
        let mut cmd = cli();
        generate(shell, &mut cmd, "genact", &mut std::io::stdout());
        return;
    }
    if matches.get_flag("print-manpage") {
        let man = clap_mangen::Man::new(cli());
        let mut out = std::io::stdout();
        man.render(&mut out).unwrap();
        return;
    }

    if matches.get_flag("list-modules") {
        println!("Available modules:");
        for name in MODULE_NAMES {
            println!("  {}", name);
