    let exit_after_time: Option<Duration> = matches.get_one("exit-after-time").copied();

    io::init(speed_factor, instant_print_lines);
    if let Some(duration) = exit_after_time {
        io::set_exit_deadline(duration);
    }

    modules::start_signal_thread();

    if matches.get_flag("inhibit") {
        io::setup_inhibit();
    }

    let selected: Vec<&modules::Module> = match matches.get_many::<String>("modules") {
        Some(values) => values.map(|v| modules::by_name(v)).collect(),
        None => modules::MODULES.iter().collect(),
    };

    let mut selected = selected;
    let mut rng = rand::thread_rng();
    selected.shuffle(&mut rng);

    let mut modules_run: u32 = 0;
    for module in selected {
        if let Some(max) = exit_after_modules {
            if modules_run >= max {
                break;
            }
        }
