{"command": "cd /workspace && python3 - <<'PY'
content = '''use std::io::{self, Write};
use std::os::unix::net::UnixStream;
use std::sync::atomic::{AtomicI64, AtomicU32, AtomicU64, AtomicUsize, Ordering};
use std::sync::OnceLock;
use std::thread;
use std::time::{Duration, Instant};

/// Global speed factor, stored as raw `f64` bits inside an atomic.
static SPEED_FACTOR: AtomicU64 = AtomicU64::new(0);
/// Lines that should be printed without sleeping in between.
static INSTANT_PRINT_LINES: AtomicU32 = AtomicU32::new(0);
/// Number of sleep points that have been reached so far.
static LINES_PRINTED: AtomicUsize = AtomicUsize::new(0);
/// Exit deadline, in milliseconds since the program started. `-1` when unused.
static EXIT_DEADLINE: AtomicI64 = AtomicI64::new(-1);
/// Printed whenever the program gets interrupted.
static EXIT_MESSAGE: &[u8] = b"Saving work to disk...\\n";
/// Time the program was started.
static PROGRAM_START: OnceLock<Instant> = OnceLock::new();
/// Connection used to keep the display awake, if one could be set up.
static INHIBIT_CONNECTION: OnceLock<UnixStream> = OnceLock::new();

/// Store the global configuration for later use.
pub fn init(speed_factor: f64, instant_print_lines: u32) {
    SPEED_FACTOR.store(speed_factor.to_bits(), Ordering::Relaxed);
    INSTANT_PRINT_LINES.store(instant_print_lines, Ordering::Relaxed);
}

/// The currently configured global speed factor.
pub fn speed_factor() -> f64 {
    f64::from_bits(SPEED_FACTOR.load(Ordering::Relaxed))
}

/// Remember that genact should exit once `duration` has passed.
pub fn set_exit_deadline(duration: Duration) {
    let deadline = Instant::now() + duration;
    let millis = deadline.duration_since(program_start()).as_millis();
    EXIT_DEADLINE.store(millis as i64, Ordering::Relaxed);
}

fn program_start() -> Instant {
    *PROGRAM_START.get_or_init(Instant::now)
}

/// Milliseconds elapsed since the program was started.
fn elapsed_millis() -> u128 {
    program_start().elapsed().as_millis()
}

/// Sleep for the given duration, scaled by the global speed factor.
///
/// Sleeps are skipped for the first `--instant-print-lines` lines, so that a
/// bunch of lines can be printed right at the start.
pub fn sleep(duration: Duration) {
    let lines = LINES_PRINTED.fetch_add(1, Ordering::Relaxed);
    if (lines as u32) <= INSTANT_PRINT_LINES.load(Ordering::Relaxed) {
        return;
    }
    let scaled = duration.as_secs_f64() * 1000.0 / speed_factor();
    let mut millis = if scaled.is_nan() { 0.0 } else { scaled.floor() };
    if millis < 0.0 {
        millis = 0.0;
    }
    thread::sleep(Duration::from_millis(millis as u64 + 1));
    check_exit_deadline();
}

/// Exit if the `--exit-after-time` deadline has passed.
fn check_exit_deadline() {
    let deadline = EXIT_DEADLINE.load(Ordering::Relaxed);
    if deadline < 0 {
        return;
    }
    if elapsed_millis() as i64 >= deadline {
        print_exit_message();
        std::process::exit(0);
    }
}

// Every write goes through this single helper so that output is always flushed
// right away, no matter whether the caller terminated its output with a
// newline or not.
fn write_out(b: &[u8]) {
    let mut stdout = io::stdout();
    // Write through the shared stdout handle so buffering stays consistent.
    stdout.write_all(&b).unwrap();
    stdout.flush().unwrap();
}

/// Print text without terminating the line.
pub fn print_raw(s: &str) {
    write_out(s.as_bytes());
}

/// Print a single line, terminated the way a terminal would do it.
pub fn print_line(line: &str) {
    write_out(line.as_bytes());
    write_out(b"\\r\\n");
}

/// Print the interrupt message. Called from the signal handling thread.
pub fn print_exit_message() {
    let mut stdout = io::stdout();
    let _ = stdout.write_all(EXIT_MESSAGE);
    let _ = stdout.flush();
}

/// Ask the session manager to keep the computer awake while genact runs.
pub fn setup_inhibit() {
    let path = inhibit_bus_path();
    match UnixStream::connect(&path) {
        Ok(stream) => {
            let _ = INHIBIT_CONNECTION.set(stream);
        }
        Err(e) => {
            println!(
                "WARN: failed to set up idle inhibition: system: I/O error: {}",
                e
            );
        }
    }
}

/// Location of the session bus socket that is used for idle inhibition.
fn inhibit_bus_path() -> String {
    if let Ok(dir) = std::env::var("XDG_RUNTIME_DIR") {
        return format!("{}/bus", dir);
    }
    let uid = unsafe { libc::getuid() };
    format!("/run/user/{}/bus", uid)
}

/// Column count of the terminal genact is attached to, if there is one.
pub fn terminal_width_opt() -> Option<u16> {
    window_size(libc::STDOUT_FILENO).or_else(|| window_size(libc::STDIN_FILENO))
