//! Minimal re-implementation of the parts of the `terminal_size` crate that are
//! needed to figure out how wide the terminal is.

/// Width of a terminal, in cells.
pub struct Width(pub u16);

/// Height of a terminal, in cells.
pub struct Height(pub u16);

/// Size of the terminal that output is written to.
pub fn terminal_size() -> Option<(Width, Height)> {
    window_size(libc::STDOUT_FILENO).or_else(|| window_size(libc::STDIN_FILENO))
}

/// Size of the terminal behind the given file descriptor.
pub fn terminal_size_of(fd: libc::c_int) -> Option<(Width, Height)> {
    window_size(fd)
}

fn window_size(fd: libc::c_int) -> Option<(Width, Height)> {
    let mut ws = libc::winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    if unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) } == 0 {
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    } else {
        None
    }
}
EOF
