    let bytes = input.as_bytes();
    let mut i = 0usize;
    let len = bytes.len();
    let mut total: u64 = 0;

    skip_whitespace(bytes, &mut i);
    if i == len {
        return Err("value was empty".to_string());
    }

    loop {
        skip_whitespace(bytes, &mut i);
        let number_start = i;
        let mut int_digits = 0usize;
        while i < len && bytes[i].is_ascii_digit() {
            i += 1;
            int_digits += 1;
        }
        let mut frac_digits = 0usize;
        let mut frac_value: u64 = 0;
        if i < len && bytes[i] == b'.' {
            let dot = i;
            i += 1;
            let frac_start = i;
            while i < len && bytes[i].is_ascii_digit() {
                i += 1;
                frac_digits += 1;
            }
            if frac_digits == 0 {
                return Err(format!("invalid character at {}", dot));
            }
            frac_value = parse_u64(&input[frac_start..i])?;
        }
        if int_digits == 0 {
            return Err(format!("expected number at {}", number_start));
        }
        let whole = parse_u64(&input[number_start..number_start + int_digits])?;
        skip_whitespace(bytes, &mut i);
        let unit_start = i;
        while i < len && (bytes[i].is_ascii_alphabetic() || bytes[i] == 0xc2 || bytes[i] == 0xb5) {
            i += 1;
        }
        let unit = &input[unit_start..i];
        if unit.is_empty() {
            if i == len {
                return Err(format!(
                    "time unit needed, for example {}sec or {}ms",
                    whole, whole
                ));
            }
            return Err(format!("invalid character at {}", unit_start));
        }
        let multiplier = match unit {
            "nanos" | "nsec" | "ns" => 1u64,
            "usec" | "us" | "\u{b5}s" => 1_000,
            "msec" | "ms" => 1_000_000,
            "seconds" | "second" | "secs" | "sec" | "s" => NANOS_IN_SECOND,
            "minutes" | "minute" | "min" | "mins" | "m" => NANOS_IN_MINUTE,
            "hours" | "hour" | "hr" | "hrs" | "h" => NANOS_IN_HOUR,
            "days" | "day" | "d" => NANOS_IN_DAY,
            "weeks" | "week" | "w" => NANOS_IN_WEEK,
            "months" | "month" | "M" => NANOS_IN_MONTH,
            "years" | "year" | "yr" | "yrs" | "y" => NANOS_IN_YEAR,
            _ => {
                return Err(format!(
                    "unknown time unit \"{}\", supported units: {}",
                    unit, SUPPORTED_UNITS
                ))
            }
        };
        let nanos = whole.checked_mul(multiplier).ok_or_else(too_large)?;
        let frac_nanos = if frac_digits > 0 {
            let div = 10u64.checked_pow(frac_digits as u32).ok_or_else(too_large)?;
            let num = frac_value.checked_mul(multiplier).ok_or_else(too_large)?;
            if num % div != 0 {
                return Err(too_large());
            }
            num / div
        } else {
            0
        };
        total = total
            .checked_add(nanos)
            .and_then(|v| v.checked_add(frac_nanos))
            .ok_or_else(too_large)?;
        if i == len {
            break;
        }
    }
    Ok(Duration::from_nanos(total))
}

fn too_large() -> String {
    "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)".to_string()
}

fn parse_u64(s: &str) -> Result<u64, String> {
    s.parse::<u64>().map_err(|_| too_large())
}

fn skip_whitespace(bytes: &[u8], i: &mut usize) {
    while *i < bytes.len() && bytes[*i].is_ascii_whitespace() {
        *i += 1;
    }
}

/// Look up a vocabulary list embedded in the binary.
pub fn vocab(name: &str) -> &'static [&'static str] {
    macro_rules! vocab {
        ($name:literal) => {{
            static CACHE: OnceLock<Vec<&'static str>> = OnceLock::new();
            CACHE.get_or_init(|| include_str!(concat!("data/", $name, ".txt")).lines().collect())
        }};
    }
    match name {
        "cargo_crates" => vocab!("cargo_crates"),
        "composer_names" => vocab!("composer_names"),
        "simcity_tasks" => vocab!("simcity_tasks"),
        "terraform_types" => vocab!("terraform_types"),
        "terraform_names" => vocab!("terraform_names"),
        "julia_pkgs" => vocab!("julia_pkgs"),
        "julia_envs" => vocab!("julia_envs"),
        "weblog_words" => vocab!("weblog_words"),
        "weblog_uas" => vocab!("weblog_uas"),
        "weblog_exts" => vocab!("weblog_exts"),
        "cc_dirs" => vocab!("cc_dirs"),
        _ => panic!("unknown vocab {}", name),
    }
}
