use crate::data;
use rand::Rng;

pub static VERSION_COMPONENT: &[(u32, u32)] = &crate::data::ver::VERSION_COMPONENT;
pub static VERSION_MAJOR: &[(u32, u32)] = &crate::data::ver::VERSION_MAJOR;

pub fn rng() -> rand::rngs::ThreadRng {
    rand::thread_rng()
}

/// Pick a random element from a slice.
pub fn pick<T>(items: &[T]) -> &T {
    &items[rand::thread_rng().gen_range(0..items.len())]
}

/// Sample a value from an empirical cumulative distribution table.
pub fn from_table(table: &[(u32, u32)]) -> u32 {
    let r: u32 = rand::thread_rng().gen_range(0..1_000_000);
    let mut idx = table.partition_point(|(_, c)| *c <= r);
    if idx >= table.len() {
        idx = table.len() - 1;
    }
    table[idx].0
}

/// A random semver like `1.17.1`.
pub fn version() -> String {
    let major = from_table(VERSION_MAJOR);
    let minor = from_table(VERSION_COMPONENT);
    let patch = from_table(VERSION_COMPONENT);
    format!("{}.{}.{}", major, minor, patch)
}

/// A random IPv4 or IPv6 address.
pub fn random_ip() -> String {
    let mut rng = rand::thread_rng();
    if rng.gen_bool(0.5) {
        format!("{}.{}.{}.{}", rng.gen_range(0..256), rng.gen_range(0..256), rng.gen_range(0..256), rng.gen_range(0..256))
    } else {
        (0..8)
            .map(|_| format!("{:x}", rng.gen_range(0..65536)))
            .collect::<Vec<_>>()
            .join(":")
    }
}

/// A random lowercase hexadecimal string of `n` characters.
pub fn random_hex(n: usize) -> String {
    let mut rng = rand::thread_rng();
    let hex = b"0123456789abcdef";
    (0..n).map(|_| hex[rng.gen_range(0..16)] as char).collect()
}

pub fn random_bytes(n: usize) -> Vec<u8> {
    let mut rng = rand::thread_rng();
    (0..n).map(|_| rng.gen_range(0..256)).collect()
}
