use std::time::Duration;
use rand::Rng;

const SPINNER: [char; 4] = ['/', '-', '\\', '|'];

pub fn run() {
    let mut rng = rand::thread_rng();
    let tasks = crate::data::vocab("simcity_tasks");
    loop {
        let task = tasks[rng.gen_range(0..tasks.len())];
        let cycles = rng.gen_range(1..20);
        for i in 0..cycles * 4 {
            if i > 0 {
