use std::time::Duration;
use rand::Rng;

fn timestamp() -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap();
    let secs = now.as_secs() % 86400;
    let (h, m, s) = (secs / 3600, (secs % 3600) / 60, secs % 60);
    format!("{:02}:{:02}:{:02}", h, m, s)
}

pub fn run() {
    let mut rng = rand::thread_rng();
    let mut gpus: u32 = 1;
    let mut base: f64 = 50.0;
    loop {
        if rng.gen_bool(0.01) {
            gpus = rng.gen_range(1..8);
            base = rng.gen_range(0.0..100.0);
        }
        let time = timestamp();
        if rng.gen_bool(0.04) {
            if rng.gen_bool(0.73) {
                crate::io::print_line(&format!(
                    "\x1b[1;36m  \u{2139}\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mstratum      \x1b[0mReceived new job #{}  seed: #{}  target: #{}",
                    time,
                    crate::modules::common::random_hex(8),
                    crate::modules::common::random_hex(32),
                    crate::modules::common::random_hex(32)
                ));
            } else {
                crate::io::print_line(&format!(
                    "\x1b[1;36m  \u{2139}\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mCUDA0        \x1b[0mSolution found; Submitted to stratum.buttcoin.org",
                    time
                ));
            }
        } else {
            let mut speeds = Vec::new();
            for _ in 0..gpus {
                speeds.push(base + rng.gen_range(-0.6..0.6));
            }
            let total: f64 = speeds.iter().sum();
            let mut line = format!(
                "\x1b[32m  m\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m{:.2}\x1b[0m Mh/s   ",
                time, total
            );
            for (i, s) in speeds.iter().enumerate() {
                line.push_str(&format!("   gpu/{} \x1b[36m{:.2}\x1b[0m", i, s));
            }
            line.push_str("   [A0+0:R0+0:F0] Time: 00:00");
            crate::io::print_line(&line);
        }
        crate::io::sleep(Duration::from_millis(rng.gen_range(50..300)));
    }
}
