use std::time::Duration;
use rand::Rng;

pub fn run() {
    let mut rng = rand::thread_rng();
    let mut addr: u64 = rng.gen_range(0..u64::MAX);
    loop {
        let bytes: Vec<u8> = (0..16).map(|_| rng.gen_range(0..256)).collect();
        let mut line = format!("{:016x}  {:02x} ", addr, bytes[0]);
        crate::io::print_raw(&line);
        for b in &bytes[1..] {
            crate::io::sleep(Duration::from_millis(1));
            crate::io::print_raw(&format!("{:02x} ", b));
            if bytes.iter().position(|x| x == b).unwrap() == 7 {
                crate::io::print_raw(" ");
            }
        }
        crate::io::sleep(Duration::from_millis(1));
        let ascii: String = bytes
            .iter()
            .map(|b| {
                if (32..127).contains(b) {
                    *b as char
                } else {
                    '.'
                }
            })
            .collect();
        crate::io::print_raw(&format!(" |{}|", ascii));
        crate::io::sleep(Duration::from_millis(rng.gen_range(30..220)));
        crate::io::print_raw("\r\n");
        addr = addr.wrapping_add(16);
    }
}
