        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line("");
        for i in 0..30 {
            let mut bar = String::new();
            for (j, color) in RAINBOW.iter().enumerate() {
                let c = if j == i {
                    ['|', '/', '-', '\\'][i % 4]
                } else if j < i {
                    '='
                } else {
                    ' '
                };
                bar.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", color, c));
            }
            crate::io::print_raw(&format!("\r=> Extracting Rainbow Table [{}]", bar));
