        }
        crate::io::print_line("=> Begin matching");
        let mut matched: Vec<bool> = hashes.iter().map(|_| false).collect();
        loop {
            for (i, hash) in hashes.iter().enumerate() {
                if progress[i] < 64 && rng.gen_bool(1.0 / 16.0) {
                    progress[i] += 1;
                }
                if progress[i] == 64 {
                    matched[i] = true;
                }
            }
            if progress.len() > 0 && progress.iter().all(|p| *p == 64) {
                break;
            }
            for (i, hash) in hashes.iter().enumerate() {
                let green = &hash[..progress[i]];
                let red = crate::modules::common::random_hex(64 - progress[i]);
                crate::io::print_line(&format!(
                    " :: \x1b[32m{}\x1b[0m\x1b[31m{}\x1b[0m ::",
                    green, red
                ));
            }
            crate::io::sleep(Duration::from_millis(11));
        }
        crate::io::print_line("=> Match found");
        for hash in hashes.iter() {
            crate::io::print_line(&format!(
                "  {}:\x1b[1m{}\x1b[0m",
                hash,
                crate::modules::bruteforce::random_name(&mut rng)
            ));
        }
    }
}
