use std::time::Duration;
use rand::Rng;

const GROUPS: [&str; 8] = [
    "group and account",
    "trojan specific",
    "filesystem",
    "malware",
    "rootkits",
    "network",
    "system tools",
    "applications",
];

pub fn run() {
    let mut rng = rand::thread_rng();
    let start = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();
    loop {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        crate::io::print_line(&format!(
            "Running Rootkit Hunter version {} on localhost",
            crate::modules::common::version()
        ));
        crate::io::sleep(Duration::from_millis(0));
        crate::io::print_line("");
        crate::io::print_line(&format!(
            "Info: Start date is {}",
            crate::modules::rkhunter::format_start_date(now)
        ));
        crate::io::print_line("");
        crate::io::print_line("Info: Detected operating system is 'Linux'");
        crate::io::print_raw(&format!(
            "Found O/S name: Ubuntu {}",
            crate::modules::common::version()
        ));
        crate::io::sleep(Duration::from_millis(0));
        crate::io::print_line("Info: Environment shell is /bin/bash; rkhunter is using dash");
        crate::io::print_line("Info: Using configuration file '/etc/rkhunter.conf'");
        crate::io::print_line("Info: Installation directory is '/usr'");
        crate::io::print_line("Info: Using language 'en'");
        for _ in 0..2 {
            crate::io::print_line("Info: Using '/var/lib/rkhunter/db' as the database directory");
            crate::io::print_line(
                "Info: Using '/usr/share/rkhunter/scripts' as the support script directory",
            );
        }
        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line("Info: Using '/usr/local/sbin /usr/local/bin /usr/sbin /usr/bin /sbin /bin /usr/games /usr/local/games /snap/bin /usr/libexec' as the command directories");
        crate::io::print_line("Info: Using '/var/lib/rkhunter/tmp' as the temporary directory");
        crate::io::print_line("Info: No mail-on-warning address configured");
        crate::io::print_line("Checking if the O/S has changed since last time...");
        crate::io::print_line("Info: Nothing seems to have changed.");
        crate::io::print_line("Info: Locking is not being used");
        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line("Starting system checks...");
        crate::io::print_line("");
        let group = GROUPS[rng.gen_range(0..GROUPS.len())];
        crate::io::print_line(&format!("Performing {} checks", group));
        let items = rng.gen_range(4..10);
        for _ in 0..items {
            let indent = if rng.gen_bool(0.3) { "    " } else { "  " };
            crate::io::print_line(&format!(
                "{}Checking for {}\x1b[0m ]",
                indent,
                crate::modules::rkhunter::random_check(&mut rng)
            ));
            crate::io::sleep(Duration::from_millis(0));
        }
        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line(&format!(
            "  {}{}\x1b[0m ]",
            group,
            " [ Not found"
        ));
        crate::io::sleep(Duration::from_millis(0));
    }
}

pub fn format_start_date(secs: u64) -> String {
    let days = (secs / 86400) as i64;
    let rem = secs % 86400;
    let date = crate::modules::weblog::civil_from_days(days);
    let (h12, ampm) = {
        let h = (rem / 3600) as u32;
        if h == 0 {
            (12u32, "AM")
        } else if h < 12 {
            (h, "AM")
        } else if h == 12 {
            (12u32, "PM")
        } else {
            (h - 12, "PM")
        }
    };
    format!(
        "{} {} {:04} {:02}:{:02}:{:02} {} UTC",
        WEEKDAYS[(days + 4) % 7 as usize],
        MONTHS[date.1 as usize - 1],
        date.2,
        date.0,
        h12,
        (rem % 3600) / 60,
        rem % 60,
        ampm
    )
}

const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

const CHECK_ITEMS: [&str; 20] = [
    "file '/lib/libsbr.so'",
    "file '/usr/doc/kern/ava'",
    "other suspicious configuration settings",
    "if syslog remote logging is allowed",
    "string /usr/lib/.../du",
    "directory '/usr/lib/kterm'",
    "file '/etc/smarvtd'",
    "file '/lib/libns5.so'",
    "file '/usr/man/man3/.../TeLeKiT/bin/teleulo'",
    "string '/dev/ptyxx/.proc'",
    "string '/lib/libext'",
    "string /dev/.lib",
    "string /usr/lib/.../lsof",
    "string /usr/sbin/.../bkit-f",
    "TCP port 47107",
    "TCP port 6667",
    "an SSH configuration file",
    "a running system logging daemon",
    "directory '/var/local/^^'",
    "file '/etc/lolzz.p2/.p2rc'",
];

pub fn random_check(rng: &mut rand::rngs::ThreadRng) -> String {
    format!("{} [ Not found", CHECK_ITEMS[rng.gen_range(0..CHECK_ITEMS.len())])
}
XEOF
echo ok"}

