use std::time::Duration;
use rand::Rng;

pub fn run() {
    let mut rng = rand::thread_rng();
    let width = crate::io::terminal_width();
    let exts = crate::data::vocab("weblog_exts");
    let crates = crate::data::vocab("cargo_crates");
    loop {
        let name = format!(
            "{}.{}",
            crates[rng.gen_range(0..crates.len())],
            exts[rng.gen_range(0..exts.len())]
        );
        let total: u64 = rng.gen_range(50..250) * 1024 * 1024;
        let name_field = name_field_width(width);
        let bar_width = bar_width(width, name_field);
        let mut downloaded: u64 = 0;
        let mut step = total / rng.gen_range(30..200);
        loop {
            let pct = ((downloaded as f64 / total as f64) * 100.0).round() as u32;
            if pct >= 100 {
                crate::io::print_line(&render(&name, 100, bar_width, name_field, 0.0, 0.0, 0, 0));
                break;
            }
            let speed = current_speed(&mut rng);
            let remaining = total.saturating_sub(downloaded);
            let eta = (remaining as f64 / speed).floor() as u64;
            crate::io::print_raw(&render(
                &name,
                pct,
                bar_width,
                name_field,
                downloaded as f64 / 1024.0 / 1024.0,
                speed / 1024.0 / 1024.0,
                eta,
                1,
            ));
            crate::io::sleep(Duration::from_millis(50));
            let chunk = rng.gen_range(1..5) * 1024 * 1024 / 4;
            downloaded += chunk.max(step / 4);
            if downloaded > total {
                downloaded = total;
            }
        }
        crate::io::print_line("");
    }
}

fn name_field_width(width: u16) -> usize {
    let avail = width as usize - 9 - 31 - 4 - 2;
    (avail * 35 / 100).max(1)
}

fn bar_width(width: u16, name_field: usize) -> usize {
    (width as usize - 9 - name_field - 4 - 2 - 31).max(1)
}

fn current_speed(rng: &mut rand::rngs::ThreadRng) -> f64 {
    let chunk: f64 = rng.gen_range(0.9..4.7) * 1024.0 * 1024.0;
    chunk * 20.0
}

fn render(
    name: &str,
    pct: u32,
    bar_width: usize,
    name_field: usize,
    size_mib: f64,
    speed_mibps: f64,
    eta: u64,
    _unused: u8,
) -> String {
    let filled = ((pct as f64 / 100.0) * bar_width as f64).floor() as usize;
    let mut bar = String::new();
    for i in 0..bar_width {
        if i < filled {
            bar.push('=');
        } else if i == filled && pct < 100 {
            bar.push('\u{2588}');
        } else {
            bar.push(' ');
        }
    }
    let size = format_size(size_mib);
    let speed = format_size(speed_mibps);
    format!(
        "\x1b[2K\x1b[0G{:<nw$}{:>4}%[{}] {:<11}{:<10}   eta {}s",
        name,
        pct,
        bar,
        size,
        format!("{}MiB/s", trim(speed)),
        eta,
        nw = name_field
    )
}

fn format_size(mib: f64) -> String {
    if mib >= 1.0 {
        format!("{:.2}MiB", mib)
    } else {
        format!("{:.2}KiB", mib * 1024.0)
    }
}

fn trim(s: String) -> String {
    s
}
