use rand::Rng;

pub fn run() {
    let mut rng = rand::thread_rng();
    let mut sent: f64 = 0.0;
    while sent < 200.0 {
        crate::io::print_raw(&format!(
            "\rSending build context to Docker daemon  {:.2}MB",
            sent
        ));
        crate::io::sleep(Duration::from_millis(50));
        sent += rng.gen_range(5.0..40.0);
    }
    crate::io::print_raw("\r\n");
    let steps = rng.gen_range(4..12);
    for i in 1..=steps {
        crate::io::print_line(&format!(
            "Step {}/{} : {}",
            i,
            steps,
            crate::modules::docker_build::random_command(&mut rng)
        ));
        crate::io::sleep(Duration::from_millis(200));
        if rng.gen_bool(0.5) {
            crate::io::print_line(&format!(
                " ---> Using cache ---> {}",
                crate::modules::common::random_hex(12)
            ));
        } else {
            crate::io::print_line(&format!(
                " ---> Running in {}",
                crate::modules::common::random_hex(12)
            ));
            crate::modules::ansible::run_once();
        }
    }
}

pub fn random_command(rng: &mut rand::rngs::ThreadRng) -> String {
    let commands = [
        "RUN mkinitcpio --generate /boot/initramfs-custom2.img --kernel 5.7.12-arch1-1",
        "RUN ansible-playbook",
        "COPY . /app",
        "RUN cargo build --release",
        "RUN apt-get update && apt-get install -y build-essential",
        "EXPOSE 8080",
        "CMD [\"./server\"]",
    ];
    commands[rng.gen_range(0..commands.len())].to_string()
}
