use std::time::Duration;
use rand::Rng;

const SUITES: [&str; 12] = [
    "css", "domxpath", "svg", "loading", "WebGL", "html", "workers", "fetch", "xhr", "encoding",
    "streams", "service-workers",
];

pub fn run() {
    let mut rng = rand::thread_rng();
    let total = rng.gen_range(100..9000);
    crate::io::print_line(&format!("Running {} tests in web-platform-tests", total));
    let mut done = 0;
    while done < total {
        let batch = rng.gen_range(1..6);
        crate::io::print_line(&format!("\x1b[A\x1b[K[{}/{}] {}", done, total, running(&mut rng)));
        for _ in 0..batch {
            crate::io::print_line(&format!(
                "    \u{25b6} Timed out in {}",
                crate::modules::common::random_hex(4)
            ));
            crate::io::print_line("    \u{2502} ERROR [expected FAIL] TIMEOUT test_ assert_");
        }
        done += batch;
        crate::io::sleep(Duration::from_millis(20));
    }
}

fn running(rng: &mut rand::rngs::ThreadRng) -> String {
    let mut parts = Vec::new();
    for _ in 0..rng.gen_range(1..8) {
        let suite = SUITES[rng.gen_range(0..SUITES.len())];
        let sub = crate::modules::common::random_hex(0);
        parts.push(format!(
            "/{}/{}/test-{}.html",
            suite,
            ["css-transforms", "render", "size-adjust"][rng.gen_range(0..3)],
            rng.gen_range(1..500)
        ));
    }
    parts.join(" ")
}
