use std::time::Duration;
use rand::Rng;

const BANNER: [&str; 9] = [
    "               \x1b[1;32m_\x1b[0m",
    "   \x1b[1;34m_\x1b[0m       _ \x1b[1;31m_\x1b[0m\x1b[1;32m(_)\x1b[0m\x1b[1;35m_\x1b[0m     |  Documentation: https://docs.julialang.org",
    "  \x1b[1;34m(_)\x1b[0m     | \x1b[1;31m(_)\x1b[0m \x1b[1;35m(_)\x1b[0m    |",
    "   _ _   _| |_  __ _   |  Type \"?\" for help, \"]?\" for Pkg help.",
    "  | | | | | | |/ _` |  |",
    "  | | |_| | | | (_| |  |  Version 1.7.3 (2022-05-06)",
    " _/ |\\__'_|_|_|\\__'_|  |  Fedora 35 build",
    "|__/                   |",
    "",
];

pub fn run() {
    let mut rng = rand::thread_rng();
    let pkgs = crate::data::vocab("julia_pkgs");
    let envs = crate::data::vocab("julia_envs");
    for line in BANNER {
        crate::io::print_line(line);
    }
    loop {
        let env = envs[rng.gen_range(0..envs.len())];
        crate::io::print_line(&format!(
            "\x1b[1;32mjulia>\x1b[0m \x1b[2K\x1b[0G\x1b[1;34m({}) pkg>\x1b[0m update",
            env
        ));
        crate::io::print_line("\x1b[1;32m    Updating\x1b[0m registry at `~/.julia/registries/General.toml`");
        crate::io::sleep(Duration::from_millis(200));
        crate::io::print_line("\x1b[1;32m   Resolving\x1b[0m package versions...");
        crate::io::sleep(Duration::from_millis(200));
        let installed = rng.gen_range(5..40);
        for _ in 0..installed {
            crate::io::print_line(&format!(
                "\x1b[1;32m   Installed\x1b[0m {} \u{2500} v{}",
                pkgs[rng.gen_range(0..pkgs.len())],
                crate::modules::common::version()
            ));
            crate::io::sleep(Duration::from_millis(20));
        }
        crate::io::sleep(Duration::from_millis(200));
        let downloads = rng.gen_range(1..6);
        for _ in 0..downloads {
            crate::io::print_line(&format!(
                "\x1b[1;32m Downloading\x1b[0m artifact: {}",
                pkgs[rng.gen_range(0..pkgs.len())]
            ));
            let mut pct: f64 = 0.0;
            while pct < 100.0 {
                crate::io::print_line(&format!(
                    "\x1b[1A\x1b[2K\x1b[0G\x1b[1;36m    Downloading\x1b[0m [{}{}] {:.2}%",
                    "=".repeat((pct / 2.5) as usize),
                    if pct < 100.0 { "\u{2588}" } else { "" },
                    pct
                ));
                crate::io::sleep(Duration::from_millis(30));
                pct += rng.gen_range(1.0..5.0);
            }
        }
        crate::io::sleep(Duration::from_millis(200));
        crate::io::print_line(&format!(
            "\x1b[1;34m({}) pkg>\x1b[0m \x1b[2K\x1b[0G\x1b[1;32mjulia>\x1b[0m ",
            env
        ));
    }
}
