                    "=".repeat((pct / 2.5) as usize),
                    if pct < 100.0 { "\u{2588}" } else { "" },
                    pct
                ));
                crate::io::sleep(Duration::from_millis(30));
                pct += rng.gen_range(1.0..5.0);
            }
        }
        crate::io::sleep(Duration::from_millis(200));
        crate::io::print_line(&format!(
            "\x1b[1;34m({}) pkg>\x1b[0m \x1b[2K\x1b[0G\x1b[1;32mjulia>\x1b[0m ",
            env
        ));
    }
}
