    }
}

/// Turn a tag template like `#.#.#-alpine` into a concrete tag.
pub fn random_tag(rng: &mut rand::rngs::ThreadRng, suffix: &str) -> String {
    if suffix == "(none)" {
        return crate::modules::common::version();
    }
    let version = crate::modules::common::version();
    let mut out = String::new();
    let mut idx = 0;
    let chars: Vec<char> = suffix.chars().collect();
    while idx < chars.len() {
        if chars[idx] == '#' {
            let width = if idx + 1 < chars.len() && chars[idx + 1] == '#' {
                idx += 1;
                2
            } else {
                1
            };
            out.push_str(&(rng.gen_range(0..10u32.pow(width))).to_string());
        } else {
            out.push(chars[idx]);
        }
        idx += 1;
    }
    if out.chars().next().map(|c| c.is_ascii_digit()) == Some(true) {
        out = format!("{}{}", version, out);
    }
    out
}
