import sys,subprocess,os,time,select,fcntl,termios,struct,pty
def cap(binp, args, cols=160, secs=1.0):
    env=dict(os.environ,TERM='xterm-256color')
    m,s=pty.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH',30,cols,0,0))
    p=subprocess.Popen([binp]+args,stdin=s,stdout=s,stderr=s,env=env,close_fds=True)
    os.close(s)
    fcntl.fcntl(m,fcntl.F_SETFL,fcntl.fcntl(m,fcntl.F_GETFL)|os.O_NONBLOCK)
    out=b''; t0=time.time()
    while time.time()-t0<secs:
        r,_,_=select.select([m],[],[],0.02)
        if r:
            try: b=os.read(m,1<<20)
            except OSError: break
            if not b: break
            out+=b
    p.send_signal(15); p.wait(); os.close(m)
    return out
b=cap('/tmp/mygenact',['-m','download'],160,1.0)
