use std::time::Duration;
use rand::Rng;

pub fn run() {
    let mut rng = rand::thread_rng();
    let width = crate::io::terminal_width();
    let exts = crate::data::vocab("weblog_exts");
    let crates = crate::data::vocab("cargo_crates");
    let vislen = width as i32 - 9;
    let name_field = ((width as i32 - 26) / 3).max(1) as usize;
    let bar_width = (vislen - name_field as i32 - 37) as usize;
    if vislen < 0 || name_field as i32 + 37 > vislen {
        loop {
            crate::io::print_line("Terminal too small to display download progress");
            crate::io::sleep(Duration::from_millis(500));
        }
    }
    loop {
        let name = format!(
            "{}.{}",
            crates[rng.gen_range(0..crates.len())],
            exts[rng.gen_range(0..exts.len())]
        );
        let total: u64 = rng.gen_range(50..250) * 1024 * 1024;
        let mut downloaded: u64 = 0;
        let first = current_chunk(&mut rng);
        crate::io::print_raw(&render(
            &name, 0, bar_width, name_field, first.0, first.1, 0, true,
        ));
        crate::io::sleep(Duration::from_millis(50));
        while downloaded < total {
            let chunk = current_chunk(&mut rng);
            downloaded = (downloaded + chunk.2).min(total);
            let pct = ((downloaded as f64 / total as f64) * 100.0).round() as u32;
            let remaining = total.saturating_sub(downloaded);
            let eta = (remaining as f64 / chunk.1).floor() as u64;
            crate::io::print_raw(&render(
                &name,
                pct,
                bar_width,
                name_field,
                chunk.0,
                chunk.1,
                eta,
                false,
            ));
            crate::io::sleep(Duration::from_millis(50));
        }
        crate::io::print_raw(&render(
            &name,
            100,
            bar_width,
            name_field,
            0.0,
            0.0,
            0,
            false,
        ));
        crate::io::print_line("");
    }
}

/// A random chunk: (size, speed in bytes/s, bytes transferred).
fn current_chunk(rng: &mut rand::rngs::ThreadRng) -> (f64, f64, u64) {
    let size: f64 = rng.gen_range(0.9..4.7) * 1024.0 * 1024.0;
    let speed = size * 20.0;
    (size, speed, (rng.gen_range(0.01..0.035) * 4.7 * 1024.0 * 1024.0) as u64)
}

fn render(
    name: &str,
    pct: u32,
    bar_width: usize,
    name_field: usize,
    size_bytes: f64,
    speed_bytes: f64,
    eta: u64,
    empty: bool,
) -> String {
    let filled = if empty {
        0
    } else {
        ((pct as f64 / 100.0) * bar_width as f64).floor() as usize
    };
    let mut bar = String::new();
    for i in 0..bar_width {
        if pct == 100 || i < filled {
            bar.push('=');
        } else if i == filled {
            bar.push('\u{2588}');
        } else {
            bar.push(' ');
        }
    }
    format!(
        "\x1b[2K\x1b[0G{:<nw$}{:>4}%[{}] {:<11}{:<10}   eta {}s",
        name,
        pct,
        bar,
        format_size(size_bytes),
        format!("{:.2}MiB/s", speed_bytes / 1024.0 / 1024.0),
        eta,
        nw = name_field
    )
}

fn format_size(bytes: f64) -> String {
    if bytes >= 1024.0 * 1024.0 {
        format!("{:.2}MiB", bytes / 1024.0 / 1024.0)
    } else {
        format!("{:.2}KiB", bytes / 1024.0)
    }
}
