{"command": "cd /workspace && cat > src/modules/uv.rs <<'XEOF'
use std::time::Duration;
use rand::Rng;

const SPINNER: [&str; 10] = [
    "\u{280b}", "\u{2819}", "\u{2839}", "\u{2838}", "\u{283c}", "\u{2834}", "\u{2826}",
    "\u{2827}", "\u{2807}", "\u{280f}",
];

/// Bytes formatted the way uv does it.
fn human(bytes: f64) -> String {
    if bytes >= 1024.0 * 1024.0 {
        format!("{:.2} MiB", bytes / 1024.0 / 1024.0)
    } else {
        format!("{:.2} KiB", bytes / 1024.0)
    }
}

pub fn run() {
    let mut rng = rand::thread_rng();
    let crates = crate::data::vocab("cargo_crates");
    loop {
        let cpython = format!("3.{}.{}", rng.gen_range(7..13), rng.gen_range(0..30));
        crate::io::print_line(&format!("Using CPython {}", cpython));
        crate::io::print_line("Creating virtualenv at: .venv");
        let count = rng.gen_range(5..200);
        for i in 0..count {
            crate::io::print_raw(&format!(
                "\x1b[2K\x1b[0G{} {}=={}",
                SPINNER[(i / count.max(1)) % SPINNER.len()],
                crates[rng.gen_range(0..crates.len())],
                crate::modules::common::version()
            ));
            crate::io::sleep(Duration::from_millis(8));
        }
        crate::io::print_line("");
        // Download progress, one package at a time.
        let mut done = 0;
        for _ in 0..count {
            let pkg = crates[rng.gen_range(0..crates.len())];
            let total: f64 = rng.gen_range(1.0..20.0) * 1024.0 * 1024.0;
            let mut downloaded = 0.0f64;
            while downloaded < total {
                let frac = downloaded / total;
                let cells = (frac * 30.0).floor() as usize;
                let bar = format!(
                    "{}{}{}",
                    "-".repeat(cells),
                    "\u{2588}",
                    " ".repeat(30 - cells - 1)
                );
                crate::io::print_line(&format!(
                    "\x1b[1A\x1b[2K\x1b[0G\x1b[2m{}\x1b[0m{}\x1b[32m{}\x1b[0m{:>12}/{}  ",
                    pkg,
                    " ".repeat(33usize.saturating_sub(pkg.len())),
                    bar,
                    human(downloaded),
                    human(total)
                ));
                crate::io::sleep(Duration::from_millis(10));
                downloaded += rng.gen_range(0.5..1.5) * 1024.0 * 1024.0;
            }
            done += 1;
        }
        // Installing wheels, tracked with a single summary bar.
        let total_wheels = count;
        for n in 0..=total_wheels {
            let cells = ((n as f64 / total_wheels as f64) * 30.0).floor() as usize;
            crate::io::print_line(&format!(
                "\x1b[1A\x1b[2K\x1b[0G\x1b[2K\x1b[0G[{}{}] [{}/{}] Installing wheels...",
                "\u{2588}".repeat(cells),
                "\u{2591}".repeat(30 - cells),
                n,
                total_wheels
            ));
            crate::io::sleep(Duration::from_millis(10));
        }
        crate::io::sleep(Duration::from_millis(200));
    }
}
