use rand::Rng;

const EXPECTED: [&str; 2] = ["PASS", "FAIL"];
const RESULTS: [&str; 3] = ["FAIL", "TIMEOUT", "ERROR"];

const AT_LOCATIONS: [&str; 8] = [
