    "http://web-platform.test:8000/:{l}:{c}",
    "assert_wrapper (http://web-platform.test:8000/resources/testharness.js:{l}:{c})",
    "test (http://web-platform.test:8000/resources/testharness.js:{l}:{c})",
    "verify (http://web-platform.test:8000/{suite}: {l}:{c})",
    "assert (http://web-platform.test:8000/resources/testharness.js:{l}:{c})",
    "testGetBoundingClientRect (http://web-platform.test:8000/resources/testharness.js:{l}:{c})",
    "http://web-platform.test:8000/{suite}:{l}:{c}",
];

pub fn run() {
    let mut rng = rand::thread_rng();
    let suites = crate::data::vocab("wpt_suites");
    let subs = crate::data::vocab("wpt_subs");
    let total = rng.gen_range(1000..15000);
    crate::io::print_line(&format!("Running {} tests in web-platform-tests", total));
    let mut done: u32 = 0;
    while done < total {
        let batch = rng.gen_range(1..20);
        let mut urls = Vec::new();
        for _ in 0..batch {
            let suite = suites[rng.gen_range(0..suites.len())];
            let sub = subs[rng.gen_range(0..subs.len())];
