    "group and account checks",
    "file properties checks",
];

const PREFIXES: [&str; 3] = ["Checking for ", "Scanning for ", "Checking if "];

pub fn run() {
    let mut rng = rand::thread_rng();
    let rootkits = crate::data::vocab("rk_rootkits");
    let items = crate::data::vocab("rk_items");
    loop {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        crate::io::print_line(&format!(
            "Running Rootkit Hunter version {} on localhost",
            crate::modules::common::version()
        ));
        crate::io::print_line("");
        crate::io::print_line(&format!(
            "Info: Start date is {}",
            crate::modules::rkhunter::format_start_date(now)
        ));
        crate::io::print_line("");
        crate::io::print_line("Info: Detected operating system is 'Linux'");
        crate::io::print_raw(&format!(
            "Found O/S name: Ubuntu {}",
            crate::modules::common::version()
        ));
        crate::io::print_line("Info: Environment shell is /bin/bash; rkhunter is using dash");
        crate::io::print_line("Info: Using configuration file '/etc/rkhunter.conf'");
        crate::io::print_line("Info: Installation directory is '/usr'");
        crate::io::print_line("Info: Using language 'en'");
        for _ in 0..2 {
            crate::io::print_line("Info: Using '/var/lib/rkhunter/db' as the database directory");
            crate::io::print_line(
                "Info: Using '/usr/share/rkhunter/scripts' as the support script directory",
            );
        }
        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line("Info: Using '/usr/local/sbin /usr/local/bin /usr/sbin /usr/bin /sbin /bin /usr/games /usr/local/games /snap/bin /usr/libexec' as the command directories");
        crate::io::print_line("Info: Using '/var/lib/rkhunter/tmp' as the temporary directory");
        crate::io::print_line("Info: No mail-on-warning address configured");
        crate::io::print_line("Checking if the O/S has changed since last time...");
        crate::io::print_line("Info: Nothing seems to have changed.");
        crate::io::print_line("Info: Locking is not being used");
        crate::io::sleep(Duration::from_millis(500));
        crate::io::print_line("Starting system checks...");
        crate::io::print_line("");
        let check = CHECKS[rng.gen_range(0..CHECKS.len())];
        crate::io::print_line(&format!("Performing {}", check));
        let groups = rng.gen_range(1..4);
        for _ in 0..groups {
            let rootkit = rootkits[rng.gen_range(0..rootkits.len())];
            crate::io::print_line(&format!("  Checking for {}...", rootkit));
            let n = rng.gen_range(4..22);
            let mut found = false;
            for _ in 0..n {
                let prefix = PREFIXES[rng.gen_range(0..PREFIXES.len())];
                let item = items[rng.gen_range(0..items.len())];
                let result = if rng.gen_bool(0.065) {
                    found = true;
                    "\x1b[31mFound"
                } else if rng.gen_bool(0.01) {
                    "Skipped"
                } else {
                    "Not found"
                };
                crate::io::print_line(&format!(
                    "    {:<75}[ {}\x1b[0m ]",
                    format!("{}{}", prefix, item),
                    result
                ));
            }
            crate::io::print_line(&format!(
                "  {:<75}[ {}\x1b[0m ]",
                rootkit,
                if found { "\x1b[31mFound" } else { "Not found" }
            ));
        }
    }
}
