/// Format the start date like rkhunter does: `Thu 19 Nov 2026 08:26:24 AM UTC`.
pub fn format_start_date(secs: u64) -> String {
    let days = (secs / 86400) as i64;
    let rem = secs % 86400;
    let date = crate::modules::weblog::civil_from_days(days);
    let hour = (rem / 3600) as u32;
    let (h12, ampm) = if hour == 0 {
        (12u32, "AM")
    } else if hour < 12 {
        (hour, "AM")
    } else if hour == 12 {
        (12u32, "PM")
    } else {
        (hour - 12, "PM")
    };
    format!(
        "{} {} {} {:04} {:02}:{:02}:{:02} {} UTC",
        WEEKDAYS[(days as usize + 4) % 7],
        date.2,
        crate::modules::weblog::MONTHS[date.1 as usize - 1],
        date.0,
        h12,
        (rem % 3600) / 60,
        rem % 60,
        ampm
    )
}

const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
